import React, { useEffect, useState } from 'react';
import ReactMarkdown from 'react-markdown';
import PropTypes from 'prop-types';
import Fade from 'react-reveal';
import { Container } from 'react-bootstrap';
import {
  SiPython,
  SiPytorch,
  SiTensorflow,
  SiOpencv,
  SiScikitlearn,
  SiFastapi,
  SiDocker,
  SiPostgresql,
  SiFirebase,
  SiLinux,
  SiGit,
  SiTypescript,
  SiJavascript,
  SiSpring,
  SiAmazonaws,
  SiTrello,
  SiJira,
  SiAndroidstudio,
  SiGradle,
  SiReact,
  SiKotlin,
} from 'react-icons/si';
import { FaJava, FaDatabase, FaSearch, FaProjectDiagram, FaChartLine, FaBrain } from 'react-icons/fa';
import Header from './Header';
import endpoints from '../constants/endpoints';
import FallbackSpinner from './FallbackSpinner';

const iconMapping = {
  Python: { component: SiPython, color: '#3776AB' },
  PyTorch: { component: SiPytorch, color: '#EE4C2C' },
  TensorFlow: { component: SiTensorflow, color: '#FF6F00' },
  YOLOv8: { component: FaProjectDiagram, color: '#00D4AA' },
  OpenCV: { component: SiOpencv, color: '#5C3EE8' },
  'scikit-learn': { component: SiScikitlearn, color: '#F09437' },
  'Hugging Face': { component: FaBrain, color: '#FFD21E' },
  'RAG Pipelines': { component: FaProjectDiagram, color: '#6366F1' },
  'Vector Search': { component: FaSearch, color: '#8B5CF6' },
  'Weights & Biases': { component: FaChartLine, color: '#FFBE00' },
  FastAPI: { component: SiFastapi, color: '#009688' },
  Docker: { component: SiDocker, color: '#2496ED' },
  PostgreSQL: { component: SiPostgresql, color: '#4169E1' },
  Firebase: { component: SiFirebase, color: '#FFCA28' },
  Linux: { component: SiLinux, color: '#FCC624' },
  Git: { component: SiGit, color: '#F05032' },
  TypeScript: { component: SiTypescript, color: '#3178C6' },
  'React Native': { component: SiReact, color: '#61DAFB' },
  Java: { component: FaJava, color: '#ED8B00' },
  Spring: { component: SiSpring, color: '#6DB33F' },
  JavaScript: { component: SiJavascript, color: '#F7DF1E' },
  SQL: { component: FaDatabase, color: '#4479A1' },
  AWS: { component: SiAmazonaws, color: '#FF9900' },
  Trello: { component: SiTrello, color: '#0079BF' },
  Jira: { component: SiJira, color: '#0052CC' },
  'Android Studio': { component: SiAndroidstudio, color: '#3DDC84' },
  Gradle: { component: SiGradle, color: '#02303A' },
  Kotlin: { component: SiKotlin, color: '#7F52FF' },
};

const styles = {
  iconContainerStyle: {
    display: 'inline-flex',
    flexDirection: 'column',
    alignItems: 'center',
    margin: 10,
    marginBottom: 0,
  },
  iconStyle: {
    height: 75,
    width: 75,
    margin: 10,
    marginBottom: 0,
  },
  reactIconStyle: {
    fontSize: 50,
    margin: 10,
    marginBottom: 0,
  },
  introTextContainer: {
    whiteSpace: 'pre-wrap',
  },
};

function Skills(props) {
  const { header } = props;
  const [data, setData] = useState(null);

  const renderSkillsIntro = (intro) => (
    <h4 style={styles.introTextContainer}>
      <ReactMarkdown>{intro}</ReactMarkdown>
    </h4>
  );

  useEffect(() => {
    fetch(endpoints.skills, {
      method: 'GET',
    })
      .then((res) => res.json())
      .then((res) => setData(res))
      .catch((err) => err);
  }, []);

  const renderIcon = (item) => {
    const mapping = iconMapping[item.title];
    if (mapping) {
      const IconComponent = mapping.component;
      return (
        <IconComponent
          style={styles.reactIconStyle}
          color={mapping.color}
          title={item.title}
        />
      );
    }
    return (
      <img
        style={styles.iconStyle}
        src={item.icon}
        alt={item.title}
      />
    );
  };

  return (
    <>
      <Header title={header} />
      {data ? (
        <Fade>
          <div className="section-content-container">
            <Container>
              {renderSkillsIntro(data.intro)}
              {data.skills?.map((rows) => (
                <div key={rows.title}>
                  <br />
                  <h3>{rows.title}</h3>
                  {rows.items.map((item) => (
                    <div key={item.title} style={styles.iconContainerStyle}>
                      {renderIcon(item)}
                      <p>{item.title}</p>
                    </div>
                  ))}
                </div>
              ))}
            </Container>
          </div>
        </Fade>
      ) : <FallbackSpinner /> }
    </>
  );
}

Skills.propTypes = {
  header: PropTypes.string.isRequired,
};

export default Skills;
